var import_obsidian4 = require("obsidian");

// src/modal.ts
var import_obsidian3 = require("obsidian");
var CreateTypstFileModal = class extends import_obsidian3.Modal {
  constructor(app, plugin) {
    super(app);
    this.fileName = "";
    this.plugin = plugin;
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    contentEl.createEl("h2", { text: "Create New Typst File" });
    new import_obsidian3.Setting(contentEl).setName("File name").setDesc("Enter the name of the Typst file (without .typ extension)").addText((text) => {
      text.setPlaceholder("note").setValue(this.fileName).onChange((value) => {
        this.fileName = value;
      });
      text.inputEl.focus();
      text.inputEl.select();
      text.inputEl.addEventListener("keydown", (e) => {
        if (e.key === "Enter") {
          this.createFile();
        }
      });
    });
    const buttonContainer = contentEl.createDiv("modal-button-container");
    const cancelButton = buttonContainer.createEl("button", { text: "Cancel" });
    cancelButton.addEventListener("click", () => {
      this.close();
    });
    const createButton = buttonContainer.createEl("button", {
      text: "Create",
      cls: "mod-cta"
    });
    createButton.addEventListener("click", () => {
      this.createFile();
    });
  }
  async createFile() {
    if (!this.fileName.trim()) {
      new import_obsidian3.Notice("Please enter a file name");
      return;
    }
    try {
      const fileName = this.fileName.trim();
      const fullPath = (0, import_obsidian3.normalizePath)(`${fileName}.typ`);
      const existingFile = this.app.vault.getAbstractFileByPath(fullPath);
      if (existingFile && existingFile instanceof import_obsidian3.TFile) {
        new import_obsidian3.Notice("File already exists");
        const leaf2 = this.app.workspace.getLeaf(true);
        leaf2.openFile(existingFile);
        this.close();
        return;
      }
      const newFile = await this.app.vault.create(fullPath, "", {});
      const leaf = this.app.workspace.getLeaf(true);
      leaf.openFile(newFile);
      this.close();
    } catch (error) {
      console.error("Error creating Typst file:", error);
      new import_obsidian3.Notice("Error creating file");
    }
  }
  onClose() {
    const { contentEl } = this;
    contentEl.empty();
  }
};

// src/commands.ts
function registerCommands(plugin) {
  plugin.addCommand({
    id: "create-typst-file",
    name: "Create new Typst file",
    callback: () => {
      new CreateTypstFileModal(plugin.app, plugin).open();
    }
  });
  plugin.addCommand({
    id: "toggle-typst-mode",
    name: "Toggle between source and reading mode",
    checkCallback: (inTypstView) => {
      const view = plugin.app.workspace.getActiveViewOfType(TypstView);
      if (view instanceof TypstView) {
        if (!inTypstView) {
          view.toggleMode();
          const mode = view.getCurrentMode();
        }
        return true;
      }
      if (!inTypstView) {
        new import_obsidian4.Notice("Must be in a Typst (.typ) file");
      }
      return false;
    }
  });
  plugin.addCommand({
    id: "export-to-pdf",
    name: "Export to PDF",
    checkCallback: (inTypstView) => {
      const view = plugin.app.workspace.getActiveViewOfType(TypstView);
      if (view instanceof TypstView) {
        if (!inTypstView) {
          view.exportToPdf();
        }
        return true;
      }
      if (!inTypstView) {
        new import_obsidian4.Notice("Must be in a Typst (.typ) file");
      }
      return false;
    }
  });
}

